-- Draft monthly overhead costing and treasury settlement; depends on 003–005.
begin;
create table erp.cost_periods(id uuid primary key default gen_random_uuid(), period_id uuid unique not null references erp.fiscal_periods, status text not null default 'open' check(status in ('open','closed')), normal_capacity_kg numeric(18,6) not null check(normal_capacity_kg>0), applied_rate_per_kg numeric(24,8) not null check(applied_rate_per_kg>=0), rate_source_period_id uuid references erp.cost_periods, check(rate_source_period_id is distinct from id));
create table erp.overheads(id uuid primary key default gen_random_uuid(), cost_period_id uuid not null references erp.cost_periods, category text not null check(category in ('labor','energy','depreciation','maintenance','rent','other')), behavior text not null check(behavior in ('fixed','variable')), amount numeric(24,8) not null check(amount>=0), journal_line_id bigint unique references erp.journal_lines);
create table erp.overhead_applications(id uuid primary key default gen_random_uuid(), cost_period_id uuid not null references erp.cost_periods, operation_id uuid unique not null references erp.operations, eligible_output_kg numeric(18,6) not null check(eligible_output_kg>0), rate numeric(24,8) not null check(rate>=0), applied_amount numeric(24,8) generated always as (round(eligible_output_kg*rate,8)) stored);
create table erp.cost_adjustments(id uuid primary key default gen_random_uuid(), cost_period_id uuid not null references erp.cost_periods, destination text not null check(destination in ('inventory','wip','cogs','abnormal_expense')), item_id uuid references erp.items, lot_id uuid references erp.lots, amount numeric(24,8) not null, journal_entry_id uuid references erp.journal_entries);
create table erp.vouchers(id uuid primary key default gen_random_uuid(), code text unique not null, kind text not null check(kind in ('receipt','payment','transfer','advance','settlement')), treasury_id uuid not null references erp.treasuries, destination_treasury_id uuid references erp.treasuries, amount numeric(24,8) not null check(amount>0), voucher_date date not null, journal_entry_id uuid unique references erp.journal_entries, check(destination_treasury_id is distinct from treasury_id), check(kind<>'transfer' or destination_treasury_id is not null));
create table erp.supplier_payment_allocations(voucher_id uuid references erp.vouchers, invoice_id uuid references erp.supplier_invoices, amount numeric(24,8) not null check(amount>0), primary key(voucher_id,invoice_id));
do $$ declare t record; begin for t in select tablename from pg_tables where schemaname='erp' loop execute format('alter table erp.%I enable row level security',t.tablename); end loop; end $$;
commit;
-- Required: prevent duplicate output counting, distinguish missing costs from zero,
-- reconcile applied vs actual overhead, expense idle capacity, and enforce allocations.
